import React, { useState } from 'react';
import { DocumentIcon, ArrowLeftIcon } from '@heroicons/react/24/solid';
import { Link } from 'react-router-dom';

const DocumentUploadPage: React.FC = () => {
  const [pdfFile, setPdfFile] = useState<File | null>(null);
  const [extractedText, setExtractedText] = useState<string>('');
  const [isLoading, setIsLoading] = useState(false);
  const [showTextSection, setShowTextSection] = useState(false);

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (file) {
      if (file.type !== 'application/pdf') {
        alert('Please upload a PDF file');
        return;
      }
      setPdfFile(file);
      setExtractedText('');
      setShowTextSection(false);
    }
  };

  const handleExtractText = async () => {
    if (!pdfFile) {
      alert('Please upload a PDF file first');
      return;
    }

    try {
      setIsLoading(true);
      const formData = new FormData();
      formData.append('file', pdfFile);
      
      const response = await fetch('http://localhost:8000/api/pdf/upload', {
        method: 'POST',
        body: formData,
      });
      
      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.detail || 'Failed to extract text from PDF');
      }
      
      const data = await response.json();
      setExtractedText(data.text);
      setShowTextSection(true);
      console.log('Text extracted successfully:', data);
    } catch (error) {
      console.error('Error extracting text:', error);
      alert(`Error extracting text: ${error instanceof Error ? error.message : 'Unknown error'}`);
    } finally {
      setIsLoading(false);
    }
  };

  const handleGenerateSpeech = async () => {
    if (!extractedText) {
      alert('Please extract text from the PDF first');
      return;
    }

    const voicePath = localStorage.getItem('voicePath');
    if (!voicePath) {
      alert('No voice model found. Please record your voice first');
      return;
    }

    try {
      setIsLoading(true);
      const response = await fetch('http://localhost:8000/api/pdf/read', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          text: extractedText,
          voice_path: voicePath,
        }),
      });
      
      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.detail || 'Failed to generate speech');
      }
      
      const data = await response.json();
      console.log('Speech generated successfully:', data);
      
      const audioUrl = new URL(data.audio_path, 'http://localhost:8000').href;
      const audio = new Audio(audioUrl);
      audio.play();
    } catch (error) {
      console.error('Error generating speech:', error);
      alert(`Error generating speech: ${error instanceof Error ? error.message : 'Unknown error'}`);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-gray-50">
      {/* Navigation */}
      <nav className="bg-white border-b border-gray-200">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between h-16">
            <div className="flex">
              <Link to="/" className="flex items-center text-gray-500 hover:text-gray-700">
                <ArrowLeftIcon className="h-5 w-5 mr-2" />
                Back to Voice Recording
              </Link>
            </div>
          </div>
        </div>
      </nav>

      {/* Progress Steps */}
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        <div className="flex items-center justify-center space-x-4 mb-8">
          <div className="flex items-center">
            <div className="w-8 h-8 bg-blue-600 text-white rounded-full flex items-center justify-center">1</div>
            <div className="ml-2 text-sm font-medium text-gray-900">Voice Recording</div>
          </div>
          <div className="w-16 h-0.5 bg-gray-200" />
          <div className="flex items-center">
            <div className="w-8 h-8 bg-blue-600 text-white rounded-full flex items-center justify-center">2</div>
            <div className="ml-2 text-sm font-medium text-gray-900">Document Upload</div>
          </div>
          <div className="w-16 h-0.5 bg-gray-200" />
          <div className="flex items-center">
            <div className="w-8 h-8 bg-gray-200 text-gray-600 rounded-full flex items-center justify-center">3</div>
            <div className="ml-2 text-sm font-medium text-gray-500">Generate Speech</div>
          </div>
        </div>

        <div className="max-w-3xl mx-auto">
          <div className="bg-white shadow sm:rounded-lg overflow-hidden">
            <div className="px-4 py-5 sm:p-6">
              <h3 className="text-lg leading-6 font-medium text-gray-900 mb-4">
                Upload your PDF document
              </h3>
              <div className="mt-2 max-w-xl text-sm text-gray-500">
                <p>Choose a PDF file to extract text and convert it to speech using your cloned voice.</p>
              </div>
              <div className="mt-5">
                <div className="flex justify-center px-6 pt-5 pb-6 border-2 border-gray-300 border-dashed rounded-lg">
                  <div className="space-y-1 text-center">
                    <DocumentIcon className="mx-auto h-12 w-12 text-gray-400" />
                    <div className="flex text-sm text-gray-600">
                      <label htmlFor="file-upload" className="relative cursor-pointer bg-white rounded-md font-medium text-blue-600 hover:text-blue-500 focus-within:outline-none focus-within:ring-2 focus-within:ring-offset-2 focus-within:ring-blue-500">
                        <span>Upload a file</span>
                        <input
                          id="file-upload"
                          name="file-upload"
                          type="file"
                          accept=".pdf"
                          className="sr-only"
                          onChange={handleFileUpload}
                        />
                      </label>
                      <p className="pl-1">or drag and drop</p>
                    </div>
                    <p className="text-xs text-gray-500">PDF up to 10MB</p>
                  </div>
                </div>
                {pdfFile && (
                  <div className="mt-4">
                    <div className="flex items-center text-sm text-gray-600">
                      <DocumentIcon className="h-5 w-5 mr-2 text-gray-400" />
                      <span className="font-medium">{pdfFile.name}</span>
                    </div>
                    {!showTextSection && (
                      <button
                        onClick={handleExtractText}
                        disabled={isLoading}
                        className="mt-4 w-full inline-flex justify-center py-2 px-4 border border-transparent shadow-sm text-sm font-medium rounded-md text-white bg-blue-600 hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-blue-500 disabled:bg-blue-300"
                      >
                        {isLoading ? 'Extracting Text...' : 'Extract Text'}
                      </button>
                    )}
                  </div>
                )}
              </div>
            </div>
          </div>

          {showTextSection && extractedText && (
            <div className="mt-8 bg-white shadow sm:rounded-lg overflow-hidden">
              <div className="px-4 py-5 sm:p-6">
                <h3 className="text-lg leading-6 font-medium text-gray-900 mb-4">
                  Extracted Text
                </h3>
                <div className="bg-gray-50 rounded-lg p-4 max-h-60 overflow-y-auto">
                  <p className="text-sm text-gray-700 whitespace-pre-wrap">{extractedText}</p>
                </div>
                <button
                  onClick={handleGenerateSpeech}
                  disabled={isLoading}
                  className="mt-4 w-full inline-flex justify-center py-2 px-4 border border-transparent shadow-sm text-sm font-medium rounded-md text-white bg-green-600 hover:bg-green-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-green-500 disabled:bg-green-300"
                >
                  {isLoading ? 'Generating Speech...' : 'Generate Speech'}
                </button>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default DocumentUploadPage;
